#!/bin/sh
# Split the wiki toh.json export into one JSON file per device.
#
# Filename = the buildbot profile id, so /downloads/ can find a device by
# the id used in /releases/{ver}/.overview.json. Most wiki entries already
# match (filename comes from the part of `deviceid` after the colon);
# the cases where they don't are listed in scripts/toh-id-overrides.tsv,
# generated by scripts/generate-toh-overrides.sh.
#
# Usage:
#   scripts/split-toh.sh [INPUT] [OUTPUT_DIR] [OVERRIDES]
# Defaults: ./static/toh/data.json -> ./static/toh/devices/, overrides
#           from ./scripts/toh-id-overrides.tsv if present.
set -eu

IN="${1:-static/toh/data.json}"
OUT="${2:-static/toh/devices}"
OVERRIDES="${3:-scripts/toh-id-overrides.tsv}"

if ! command -v jq >/dev/null 2>&1; then
  printf 'split-toh.sh: jq is required but not installed\n' >&2
  exit 1
fi

if [ ! -f "$IN" ]; then
  printf 'split-toh.sh: input file not found: %s\n' "$IN" >&2
  exit 1
fi

mkdir -p "$OUT"
find "$OUT" -name '*.json' -type f -delete

[ -f "$OVERRIDES" ] || OVERRIDES=""

jq -rc '
  .columns as $cols
  | .entries[]
  | . as $entry
  | ([range(0; $cols | length)]
      | map({key: $cols[.], value: $entry[.]})
      | from_entries) as $obj
  | (($obj.deviceid // "_unknown") + "\t" + ($obj | tojson))
' "$IN" | awk -F'\t' -v overrides="$OVERRIDES" -v outdir="$OUT" '
BEGIN {
  if (overrides != "") {
    while ((getline line < overrides) > 0) {
      if (line ~ /^#/ || line == "") continue;
      tab = index(line, "\t");
      if (tab > 0) ovr[substr(line, 1, tab - 1)] = substr(line, tab + 1);
    }
    close(overrides);
  }
}
{
  did = $1;
  json = $2;
  # Strip the <brand>: prefix to get the wiki suffix.
  colon = index(did, ":");
  suf = (colon > 0) ? substr(did, colon + 1) : did;
  # Apply override if present, else use the wiki suffix as the filename.
  name = (suf in ovr) ? ovr[suf] : suf;
  gsub(/[^A-Za-z0-9._-]/, "_", name);

  fpath = outdir "/" name ".json";
  print json > fpath;
  close(fpath);
  count++;
}
END {
  printf "split-toh.sh: %d devices to %s\n", count, outdir > "/dev/stderr";
}
'
